// ELEMENTS:
// 1. Navy com o filete vermelho no topo e raios de luz azul royal a rodar devagar por trás
// 2. Eyebrow + título (anim.text)
// 3. Monumento (frontão e colunas) que se desenha a branco e se enche de azul royal
// 4. Carimbo redondo vermelho com texto em círculo (stamp) a cair rodado sobre o monumento
// 5. Chips azuis (items) a entrar nos tempos da voz (times, s); grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.8));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.07, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const SeloClassificado: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const pid = useId().replace(/:/g, "");
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const eyebrow = String(p.eyebrow ?? "").trim();
  const stampText = String(p.stamp ?? "").trim();
  const stampAt = Number(p.stampAt ?? 1.2) || 1.2;
  const items = Array.isArray(p.items) ? (p.items as unknown[]).map(String) : [];
  const times = Array.isArray(p.times) ? (p.times as unknown[]).map(Number) : [];
  const title = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const draw = show(0.1, 1.1);
  const fill = show(0.9, 0.6);
  const stamp = show(stampAt, 0.5, BACK);
  const spin = (f / fps) * 6;
  const ring = `${stampText} · ${stampText} · `;

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center" }}>
        <svg width={W * 1.6} height={W * 1.6} viewBox="-100 -100 200 200" style={{ position: "absolute", top: -W * 0.25, opacity: 0.35 * show(0, 1) }}>
          {Array.from({ length: 12 }, (_, i) => (
            <path key={i} d="M0 0 L-6 -100 L6 -100 Z" fill={BLUE} transform={`rotate(${i * 30 + spin})`} />
          ))}
        </svg>
      </AbsoluteFill>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 44 * u }}>
        <div style={{ position: "relative" }}>
          <svg width={560 * u} height={480 * u} viewBox="0 0 120 104" style={{ overflow: "visible" }}>
            <path d="M14 36 L60 8 L106 36 Z" fill={BLUE} opacity={fill} />
            {[26, 44, 70, 88].map((x, i) => <rect key={i} x={x - 4} y={46} width={8} height={42} fill={BLUE} opacity={fill} />)}
            <path d="M14 36 L60 8 L106 36 Z M20 44 H100 M26 46 V88 M44 46 V88 M70 46 V88 M88 46 V88 M16 90 H104 M10 98 H110" fill="none" stroke={WHITE} strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={1} strokeDashoffset={1 - draw} />
          </svg>
          {stampText ? (
            <svg width={300 * u} height={300 * u} viewBox="-100 -100 200 200" style={{ position: "absolute", right: -120 * u, bottom: -60 * u, opacity: stamp, transform: `rotate(${-14 + (1 - stamp) * 40 + spin * 0.5}deg) scale(${stamp > 0 ? 0.6 + 0.4 * stamp + (1 - stamp) * 0.9 : 0})`, filter: "drop-shadow(0 14px 24px rgba(0,0,0,0.45))" }}>
              <defs><path id={pid} d="M0 -70 A70 70 0 1 1 -0.01 -70" /></defs>
              <circle r={96} fill={RED} />
              <circle r={84} fill="none" stroke={WHITE} strokeWidth={3} />
              <circle r={52} fill="none" stroke={WHITE} strokeWidth={2} />
              <text fill={WHITE} style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 17, letterSpacing: 3 }}>
                <textPath href={`#${pid}`}>{ring.toUpperCase()}</textPath>
              </text>
              <path d="M-22 0 L-6 16 L24 -16" fill="none" stroke={WHITE} strokeWidth={8} strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          ) : null}
        </div>
        {eyebrow ? (
          <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 30 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: MIST, opacity: show(0.3) }}>
            <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
            {eyebrow}
          </div>
        ) : null}
        <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 104 * u, lineHeight: 1.05, color: WHITE, textAlign: "center", opacity: show(0.45), transform: `translateY(${(1 - show(0.45)) * 26 * u}px)` }}>{title}</div>
        <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: 18 * u, maxWidth: 920 * u }}>
          {items.map((it, i) => {
            const k = show(Number.isFinite(times[i]) ? times[i] : 1.6 + i * 0.4, 0.45, BACK);
            return <div key={i} style={{ background: BLUE, color: WHITE, borderRadius: 999, padding: `${16 * u}px ${34 * u}px`, fontFamily: FONTS.body, fontWeight: 600, fontSize: 32 * u, opacity: Math.min(1, k * 1.5), transform: `scale(${k})` }}>{it}</div>;
          })}
        </div>
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default SeloClassificado;
